def label(unit):
    w = unit.get('why_included', '') or ''
    if unit.get('disposition') != 'included':
        return ('not included', 1.0)
    code = any(p in w for p in [
        'Supplied task-specific code',
        'custom-program rule',
        'Decoded submitted HTML contains task-specific',
        'Submitted automatic form targets',
        'Payload-bearing request',
        'reflected-script probe',
    ])
    if code:
        return ('task code or payload', 1.0)
    inter = any(p in w for p in [
        'uses an intermediary or publishes task material',
        'Encoded submitted content publishes',
        'requested through Jina',
    ])
    if inter:
        return ('intermediary', 1.0)
    other = any(p in w for p in [
        'Explicitly reviewed activity family',
        'Daniel selected',
        'Explicit reference or discovery candidate',
        'Direct Quidax',
        'HTML-bearing status-message',
    ])
    if 'Related data source or exact task identifier' in w and not other:
        return ('source match only', 1.0)
    return ('other evidence', 1.0)
